function safeLesson(value){try{if(!value)return null;const lesson=C.parseLesson(JSON.stringify({resumen:value.summary,tarjetas:value.cards?.map(c=>({pregunta:c.question,respuesta:c.answer})),guion:value.script}));if(value.outline){try{lesson.outline=C.parseOutline(JSON.stringify({esquema:value.outline.map(s=>({titulo:s.title,puntos:s.points}))}));}catch(_){/* Ignore an invalid optional outline. */}}return lesson;}catch(_){return null;}}
