 $("#make-lesson")?.addEventListener("click",async()=>{if(busy)return;const m=st.materials.find(x=>x.id===currentMaterial);if(!m)return;markBusy(true,"Preparando resumen, tarjetas y narración…");try{
  const answer=await gemini(`Crea una lección para estudiar este material en español. Usa únicamente hechos presentes en el texto; si el material es insuficiente, dilo y evita inventar. Devuelve SOLO JSON válido con esta estructura: {"resumen":["idea concreta 1","idea concreta 2","idea concreta 3"],"tarjetas":[{"pregunta":"...","respuesta":"..."},{"pregunta":"...","respuesta":"..."}],"guion":"Introducción breve, explicación de las ideas en lenguaje oral y recapitulación final, aproximadamente 2 a 4 minutos de lectura."}. Escribe de 3 a 5 ideas, de 3 a 5 tarjetas y un guion de máximo 3000 caracteres. MATERIAL (${m.name}):\n${m.text.slice(0,21000)}`);
  m.lesson=C.parseLesson(answer);await persist("ff_materials",st.materials);render();toast("Tu lección está lista.");
 }catch(err){toast(err.message,true);}finally{markBusy(false);}});
 document.querySelectorAll("[data-flip]").forEach(button=>button.addEventListener("click",()=>{const panel=$(`#lesson-answer-${button.dataset.flip}`);panel.hidden=!panel.hidden;button.textContent=panel.hidden?"Mostrar respuesta":"Ocultar respuesta";button.setAttribute("aria-expanded",String(!panel.hidden));}));
 $("#play-lesson")?.addEventListener("click",()=>{const script=safeLesson(st.materials.find(x=>x.id===currentMaterial)?.lesson)?.script;if(!script)return;stopNarration();speakLesson(script);});
