 const showSlide=()=>{if(!ideas.length)return;$("#video-count").textContent=`IDEA ${videoSlide+1} / ${ideas.length}`;$("#video-idea").textContent=ideas[videoSlide];$("#video-stage").classList.remove("slide-in");void $("#video-stage").offsetWidth;$("#video-stage").classList.add("slide-in");};
