async function gemini(prompt,{attachment=null,history=[]}={}){
 if(!apiKey)throw Error("Necesitas una clave Gemini. Ve a Configuración para conectarla.");
 const model=st.config.model||"gemini-flash-latest";
 if(!/^[a-zA-Z0-9._-]{3,65}$/.test(model))throw Error("Identificador de modelo inválido.");
 const contents=history.map(h=>({role:h.role==="assistant"?"model":"user",parts:[{text:String(h.text).slice(0,6000)}]}));
 const parts=[{text:prompt}];if(attachment)parts.push({inline_data:attachment});contents.push({role:"user",parts});
 const controller=new AbortController();const t=setTimeout(()=>controller.abort(),75000);
 try{
  const r=await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(model)}:generateContent`,{
   method:"POST",headers:{"Content-Type":"application/json","x-goog-api-key":apiKey},body:JSON.stringify({contents,generationConfig:{temperature:0.35,maxOutputTokens:3500}}),signal:controller.signal
  });
  const json=await r.json().catch(()=>({}));
  if(!r.ok)throw Error(`Gemini (${r.status}): ${(json.error?.message||"No se pudo generar contenido").slice(0,250)}`);
  const text=(json.candidates?.[0]?.content?.parts||[]).map(x=>x.text||"").join("\n").trim();
  if(!text)throw Error("Gemini no devolvió texto. Inténtalo otra vez o cambia de modelo.");
  return text;
 }catch(err){if(err.name==="AbortError")throw Error("La solicitud tardó demasiado. Comprueba la conexión o usa un archivo más pequeño.");throw err;}finally{clearTimeout(t);}
}
function materialOptions(selected,includeGeneral=false){return `${includeGeneral?'<option value="">Sin material / preguntas generales</option>':""}${st.materials.map(m=>`<option value="${E(m.id)}" ${selected===m.id?"selected":""}>${E(m.name)}</option>`).join("")}`;}
function director(){const mat=st.materials.find(m=>m.id===chatMaterial);const msgs=st.chat.filter(m=>m.materialId===chatMaterial).slice(-14);return `${header("03 / ASISTENCIA","Director IA","Resuelve dudas con Gemini usando tus apuntes como contexto. La IA puede equivocarse: contrasta las respuestas con tu material.")}
 ${!apiKey?'<div class="notice">Para hablar con el Director, añade tu propia clave Gemini en Configuración. El temporizador y los bloqueos funcionan sin clave.</div>':""}
 <div class="panel"><div class="fields"><div class="field"><label for="ai-material">Material para conversar</label><select id="ai-material">${materialOptions(chatMaterial,true)}</select></div><button id="explain-plan" class="button ai-action">✦ Proponer método</button></div><p class="tiny">${mat?`Contexto: ${E(mat.name)} · ${E(C.chooseMethod(mat.text,mat.name).name)} sugerido`:"Sin documento seleccionado; puedes hacer preguntas generales."}</p>
 <div class="message-list" id="messages">${msgs.map(m=>`<div class="bubble ${m.role==="user"?"user":"assistant"}"><span class="who">${m.role==="user"?"TÚ":"DIRECTOR IA"}</span>${E(m.text)}</div>`).join("")||'<div class="empty">Formula una pregunta sobre tus asignaturas o selecciona un material para empezar.</div>'}</div><form id="ask-form" style="margin-top:13px"><div class="fields"><div class="field"><label for="question-ai">Tu pregunta</label><input id="question-ai" maxlength="1500" placeholder="Ej.: Explícame la fotosíntesis con tres ejemplos…" required /></div><button class="button primary ai-action" ${apiKey?"":"disabled"}>Enviar ↗</button></div></form><div id="busy-status" class="loading"></div></div>
 <div class="panel"><h2>⚙ Tu control, tu ritmo</h2><p>Elige entre las sugerencias de estudio. El asistente puede recomendar un método, pero no modifica tus bloqueos ni horarios sin tu decisión.</p></div>`;}
function bindDirector(){
 const msglist=$("#messages");msglist.scrollTop=msglist.scrollHeight;
 $("#ai-material").addEventListener("change",e=>{chatMaterial=e.target.value;render();});
 $("#explain-plan").addEventListener("click",async()=>{if(busy)return;const m=st.materials.find(x=>x.id===chatMaterial);if(!m)return toast("Selecciona primero un material.",true);markBusy(true,"Preparando sugerencia…");try{const text=await gemini(`Toma SOLO el material siguiente y propone un método de estudio entre Crono-Asalto, El Manicomio e Inmersión Fluida. Explica cuál y da un plan REALISTA de 25 minutos. No prometas eficacia clínica.\nMATERIAL:\n${m.text.slice(0,21000)}`);st.chat=[...st.chat,{id:crypto.randomUUID(),materialId:chatMaterial,role:"assistant",text,at:Date.now()}].slice(-80);await persist("ff_chat",st.chat);render();}catch(err){toast(err.message,true);}finally{markBusy(false);}});
 $("#ask-form").addEventListener("submit",async e=>{e.preventDefault();if(busy)return;const q=$("#question-ai").value.trim();if(!q)return;const m=st.materials.find(x=>x.id===chatMaterial);const history=st.chat.filter(x=>x.materialId===chatMaterial).slice(-8);st.chat=[...st.chat,{id:crypto.randomUUID(),materialId:chatMaterial,role:"user",text:q,at:Date.now()}].slice(-80);await persist("ff_chat",st.chat);render();markBusy(true,"El Director está escribiendo…");try{
 const prompt=`Eres el Director de FocusForge, un tutor de estudio directo, exigente pero respetuoso. No hagas diagnósticos médicos ni prometas resultados. Si falta información, dilo. Responde en español. ${m?`Basarte principalmente en estos apuntes y señalar cuando una respuesta no aparece en ellos:\n${m.text.slice(0,18000)}`:"No hay apuntes adjuntos."}\nConsulta actual: ${q}`;
 const response=await gemini(prompt,{history:history.map(h=>({role:h.role,text:h.text}))});
 st.chat=[...st.chat,{id:crypto.randomUUID(),materialId:chatMaterial,role:"assistant",text:response,at:Date.now()}].slice(-80);await persist("ff_chat",st.chat);render();
 }catch(err){toast(err.message,true);st.chat=[...st.chat,{id:crypto.randomUUID(),materialId:chatMaterial,role:"assistant",text:`No se pudo consultar la IA: ${err.message}`,at:Date.now()}].slice(-80);await persist("ff_chat",st.chat);render();}finally{markBusy(false);}});
}
function exams(){if(!st.materials.some(x=>x.id===currentMaterial)&&st.materials.length)currentMaterial=st.materials[0].id;const m=st.materials.find(x=>x.id===currentMaterial);
 if(!quiz){return `${header("04 / RETOS","Sala de exámenes","Sube tus ejercicios o elige apuntes guardados. La IA creará un examen y explicará tus fallos después de corregirlo.")}${!apiKey?'<div class="notice">Para generar preguntas y explicar fallos necesitas tu clave Gemini en Ajustes y conexión a Internet. Tus archivos se envían a Google solo cuando utilizas IA.</div>':""}<section class="panel"><h2>1. Sube una hoja de ejercicios</h2><p>Texto (.txt, .md o .csv); PDF o imagen (.pdf, .jpg, .png, .webp) con IA. Máximo 8 MB para PDF e imagen. Revisaremos las respuestas importantes: la IA puede equivocarse.</p><button id="exam-upload" class="button primary ai-action" ${!apiKey?"disabled":""}>↟ Subir ejercicios y crear examen</button><input id="exam-file" type="file" class="file-input" accept=".txt,.md,.csv,.pdf,.png,.jpg,.jpeg,.webp,text/plain,text/markdown,application/pdf,image/png,image/jpeg,image/webp"/><hr class="line"/><h2>2. O elige material que ya subiste</h2><div class="field"><label for="exam-material">Material a evaluar</label><select id="exam-material">${materialOptions(currentMaterial,false)}</select></div><div class="actions"><button id="create-quiz" class="button ai-action" ${(!apiKey||!m)?"disabled":""}>⚔ Crear examen</button></div><div id="busy-status" class="loading"></div></section>`;}
 const {questions,done,answers}=quiz;
 return `${header("04 / RETOS","Sala de exámenes",`Tema: ${E(quiz.materialName)} · ${questions.length} preguntas`)}`+
 `<section class="panel"><form id="quiz-form">${questions.map((q,i)=>`<div class="question"><div class="eyebrow">PREGUNTA ${i+1} / ${questions.length}</div><h3>${E(q.pregunta)}</h3>${q.opciones.map((o,j)=>`<label class="option"><input type="radio" name="q${i}" value="${j}" ${done?"disabled":""} ${answers&&answers[i]===j?"checked":""}/><span>${E(o)}</span></label>`).join("")}${done?`<div class="feedback ${answers[i]===q.correcta?"good":"bad"}">${answers[i]===q.correcta?"✓ Correcto":"✕ Incorrecto"} · Respuesta: ${E(q.opciones[q.correcta])}<br/>${E(q.explicacion)}${quiz.help?.[i]?`<div class="ai-feedback"><strong>✦ Ayuda de IA:</strong> ${E(quiz.help[i].explanation)}${quiz.help[i].practice?`<br/><strong>Para practicar:</strong> ${E(quiz.help[i].practice)}`:""}</div>`:""}</div>`:""}</div>`).join("")}${done?`<div class="result">Resultado: ${quiz.score}/${questions.length} aciertos. Has ganado ${quiz.score*5} XP y ${quiz.score*2} monedas. ${questions.length-quiz.score} error(es) enviado(s) al Baúl.${quiz.aiSummary?`\n\nConsejo de IA: ${E(quiz.aiSummary)}`:""}</div><div id="busy-status" class="loading"></div><div class="actions"><button type="button" id="retry" class="button">Nuevo examen</button><button type="button" id="go-errors" class="button primary">Repasar errores →</button></div>`:'<button class="button primary" type="submit">Corregir examen</button><button type="button" id="cancel" class="button">Salir sin guardar</button>'}</form></section>`;
}
async function generateExam(m){
 if(busy||!m)return;markBusy(true,"La IA está preparando preguntas basadas en tus ejercicios…");try{
  const response=await gemini(`Actúa como un profesor que prepara una prueba de clase de esta asignatura. Crea EXACTAMENTE 5 preguntas variadas: 2 de comprensión, 2 de aplicación a ejemplos o ejercicios y 1 que exija detectar un error habitual. Contextualiza cada enunciado, reparte la respuesta correcta entre distintas posiciones y diseña distractores plausibles, sin trampas ni ambigüedades. Si hay ejercicios, usa ejercicios resolubles a partir del material. No inventes datos ni soluciones sin respaldo. Cuatro opciones, solo una correcta (índice 0-3), y explicación con la pista concreta de los apuntes que permite comprobarla. Devuelve SOLO JSON válido: {"preguntas":[{"pregunta":"…","opciones":["…","…","…","…"],"correcta":0,"explicacion":"…"}]}. MATERIAL:\n${m.text.slice(0,23000)}`);
  const questions=C.parseQuiz(response);quiz={materialId:m.id,materialName:m.name,questions,done:false,answers:null,score:0};render();
 }catch(err){toast(err.message,true)}finally{markBusy(false);}
}
function bindExams(){
 if(!quiz){$("#exam-material")?.addEventListener("change",e=>{currentMaterial=e.target.value;render();});
  $("#create-quiz")?.addEventListener("click",()=>generateExam(st.materials.find(x=>x.id===currentMaterial)));
  $("#exam-upload")?.addEventListener("click",()=>$("#exam-file").click());
  $("#exam-file")?.addEventListener("change",async e=>{if(!apiKey)return toast("Configura Gemini en Ajustes para crear el examen.",true);const added=await handleFiles(e.target.files);if(added.length)await generateExam(added[added.length-1]);});return;}
 $("#retry")?.addEventListener("click",()=>{quiz=null;render();});$("#go-errors")?.addEventListener("click",()=>navigate("errors"));$("#cancel")?.addEventListener("click",()=>{quiz=null;render();});
 $("#quiz-form").addEventListener("submit",async e=>{e.preventDefault();if(quiz.done)return;const answers=quiz.questions.map((_,i)=>{const choice=$("input[name=q"+i+"]:checked");return choice?Number(choice.value):null;});if(answers.some(x=>x===null))return toast("Responde todas las preguntas antes de corregir.",true);
 const wrong=quiz.questions.flatMap((q,i)=>answers[i]===q.correcta?[]:[{id:crypto.randomUUID(),quizIndex:i,materialId:quiz.materialId,subject:quiz.materialName,question:q.pregunta,answer:q.opciones[q.correcta]+". "+q.explicacion,successes:0,dueAt:Date.now(),at:Date.now()}]);
 st.errors=[...wrong,...st.errors].slice(0,200);quiz.answers=answers;quiz.score=quiz.questions.filter((q,i)=>q.correcta===answers[i]).length;quiz.done=true;
 try{await persist("ff_errors",st.errors);await msg("REWARD_QUIZ",{correct:quiz.score});toast("Examen corregido y errores guardados.");}catch(err){toast(err.message,true);}render();
 if(!wrong.length||!apiKey)return;
 const graded=quiz;markBusy(true,"Analizando tus fallos y preparando las tarjetas…");
 try{
  const m=st.materials.find(x=>x.id===graded.materialId);
  const mistakes=wrong.map(card=>({indice:card.quizIndex,pregunta:card.question,tu_respuesta:graded.questions[card.quizIndex].opciones[answers[card.quizIndex]],respuesta_correcta:graded.questions[card.quizIndex].opciones[graded.questions[card.quizIndex].correcta],explicacion:graded.questions[card.quizIndex].explicacion}));
  const response=await gemini(`Eres un tutor que analiza fallos de un examen. Para CADA error explica qué concepto se confundió y cómo repasarlo con un ejercicio breve. Basa la explicación en estos apuntes, no inventes hechos y señala si falta información. No culpes al estudiante. Devuelve SOLO JSON: {"ayudas":[{"indice":0,"explicacion":"...","practica":"..."}],"resumen":"consejo breve"}. Los índices deben coincidir con los de los fallos. APUNTES:\n${(m?.text||"").slice(0,14000)}\nFALLOS:\n${JSON.stringify(mistakes).slice(0,11000)}`);
  const advice=C.parseMistakeHelp(response,graded.questions.length);
  const wrongIndexes=new Set(wrong.map(card=>card.quizIndex));
  graded.help=Object.fromEntries([...advice.help].filter(([index])=>wrongIndexes.has(index)));graded.aiSummary=advice.summary;
  for(const card of wrong){const help=advice.help.get(card.quizIndex);if(help)card.aiHelp=`${help.explanation}${help.practice?"\nPara practicar: "+help.practice:""}`;}
  await persist("ff_errors",st.errors);
  if(quiz===graded)render();toast("La IA ha añadido explicaciones a tus fallos.");
 }catch(err){toast("Las tarjetas se guardaron. La explicación de IA no se pudo generar: "+err.message,true);}finally{markBusy(false);}
 });
}
function errorVault(){const due=st.errors.filter(e=>e.dueAt<=Date.now()).sort((a,b)=>a.dueAt-b.dueAt);const next=st.errors.filter(e=>e.dueAt>Date.now()).sort((a,b)=>a.dueAt-b.dueAt);return `${header("05 / RECUPERACIÓN","Baúl de las Sombras","Aquí vuelven las preguntas que fallaste. Repásalas en intervalos orientativos de 1, 3, 7 y 14 días.")}
 <div class="stats" style="grid-template-columns:repeat(2,minmax(0,1fr))"><div class="stat"><small>REPASOS DISPONIBLES</small><strong>${due.length}</strong></div><div class="stat"><small>PROGRAMADOS</small><strong>${next.length}</strong></div></div>
 <section class="panel"><h2>🎯 Para repasar ahora</h2>${due.map((c,i)=>`<div class="question"><div class="eyebrow">${E(c.subject||"Repaso manual")} · TARJETA ${i+1}</div><h3>${E(c.question)}</h3><button class="button sm" data-reveal="${E(c.id)}">Ver respuesta</button><div class="answer" id="answer-${E(c.id)}" hidden>${E(c.answer)}${c.aiHelp?`<div class="ai-feedback"><strong>✦ La IA te ayuda:</strong><br/>${E(c.aiHelp)}</div>`:""}</div><div class="actions" id="grade-${E(c.id)}" hidden><button class="button sm danger" data-grade="${E(c.id)}" data-good="false">No lo recordaba</button><button class="button sm primary" data-grade="${E(c.id)}" data-good="true">Lo he recordado</button></div></div>`).join("")||'<div class="empty">¡Nada pendiente! Los nuevos errores aparecerán aquí después de un examen o al añadir una tarjeta.</div>'}</section>
 <div class="columns-2"><section class="panel"><h2>+ Añadir tarjeta manual</h2><form id="manual-error"><div class="field"><label for="manual-subject">Asignatura</label><input id="manual-subject" maxlength="65" placeholder="Matemáticas" /></div><div class="field" style="margin-top:10px"><label for="manual-question">Pregunta</label><textarea id="manual-question" rows="3" maxlength="600" required></textarea></div><div class="field" style="margin-top:10px"><label for="manual-answer">Respuesta</label><textarea id="manual-answer" rows="3" maxlength="700" required></textarea></div><div class="actions"><button class="button primary" type="submit">Guardar para repasar</button></div></form></section>
 <section class="panel"><h2>◷ Próximos repasos</h2>${next.slice(0,12).map(c=>`<div class="plan-item"><div><strong>${E(c.question.slice(0,70))}</strong><br/><small>${E(c.subject||"General")} · ${fmt(c.dueAt)}</small></div><button class="button sm danger" data-forget="${E(c.id)}">✕</button></div>`).join("")||'<p class="tiny">Aún no hay tarjetas programadas.</p>'}<p class="tiny">Los intervalos son una estrategia de repaso, no una garantía de memorización.</p></section></div>`;}
function bindErrors(){
 document.querySelectorAll("[data-reveal]").forEach(b=>b.addEventListener("click",()=>{$(`#answer-${b.dataset.reveal}`).hidden=false;$(`#grade-${b.dataset.reveal}`).hidden=false;b.hidden=true;}));
 document.querySelectorAll("[data-grade]").forEach(b=>b.addEventListener("click",async()=>{const e=st.errors.find(x=>x.id===b.dataset.grade);if(!e)return;const updated=C.nextReview(e,b.dataset.good==="true",Date.now());st.errors=st.errors.map(x=>x.id===e.id?updated:x);await persist("ff_errors",st.errors);render();toast("Próxima revisión programada.");}));
 document.querySelectorAll("[data-forget]").forEach(b=>b.addEventListener("click",async()=>{st.errors=st.errors.filter(x=>x.id!==b.dataset.forget);await persist("ff_errors",st.errors);render();}));
 $("#manual-error").addEventListener("submit",async e=>{e.preventDefault();const question=$("#manual-question").value.trim(),answer=$("#manual-answer").value.trim(),subject=$("#manual-subject").value.trim()||"General";if(!question||!answer)return toast("Completa la pregunta y la respuesta.",true);st.errors=[{id:crypto.randomUUID(),subject,question,answer,successes:0,dueAt:Date.now(),at:Date.now()},...st.errors].slice(0,200);await persist("ff_errors",st.errors);render();toast("Tarjeta guardada.");});
}
function settings(){return `${header("06 / PERSONALIZACIÓN","Centro de control","Configura tu IA y protege tus datos en esta tablet.")}
 <section class="panel"><h2>📵 Concentración en tablet</h2><div class="notice info">Esta versión es una aplicación Android independiente. No bloquea otras aplicaciones ni el dispositivo. Para establecer límites utiliza los controles del sistema.</div><div class="actions"><a class="button" href="https://support.google.com/android/answer/9346420?hl=es" target="_blank" rel="noopener">Bienestar digital · Android ↗</a></div><p>El temporizador se actualiza cuando vuelves a la app. Si cierras la app, no puede enviarte alarmas fiables ni impedir que uses otras aplicaciones.</p></section>
 <section class="panel"><h2>✦ Conectar inteligencia artificial</h2><p>Para consultar apuntes, procesar PDFs o generar exámenes necesitas tu <strong>propia clave de Gemini</strong> y conexión a Internet. Cuando utilizas IA, tus consultas y archivos se envían directamente a Google.</p><div class="notice">En Android puedes guardar la clave cifrada en esta tablet mediante Android Keystore y volver a usarla cuando abras la app. Si alguien tiene acceso a la aplicación desbloqueada, puede utilizar la IA. La clave nunca aparece en el ZIP, GitHub ni las copias de FocusForge. Iniciar sesión con Google no configura Gemini automáticamente. El proveedor puede aplicar cuotas y cargos.</div><div class="field" style="margin-top:16px"><label for="gemini-key">Clave de Google AI Studio</label><input id="gemini-key" type="password" autocomplete="off" placeholder="${apiKey?"Clave conectada · deja vacío para conservarla":"Pega tu clave personal"}"/></div><label class="checkbox-line" style="margin-top:12px"><input id="remember-key" type="checkbox" ${window.FocusForgeAndroid?.saveGeminiKey?"checked":"disabled"}/> Recordar cifrada en esta tablet (Android)</label><div class="field" style="margin-top:12px"><label for="gemini-model">Modelo de IA</label><input id="gemini-model" value="${E(st.config.model)}" placeholder="gemini-flash-latest" maxlength="65"/></div><div class="actions"><button id="save-ai" class="button primary">Guardar conexión</button><button id="test-ai" class="button ai-action">Probar IA</button><button id="forget-key" class="button danger">Quitar clave</button><a href="https://aistudio.google.com/app/apikey" target="_blank" rel="noopener noreferrer" class="button">Obtener clave ↗</a></div><div id="busy-status" class="loading"></div></section>
 <section class="panel"><h2>▤ Copias y privacidad</h2><p>Los apuntes, errores, XP e historial se guardan <strong>solo en esta aplicación de Android</strong>. No se sincronizan automáticamente con Chromebook ni con otros dispositivos. Exporta e importa una copia para trasladarlos.</p><div class="actions"><button id="export-data" class="button">⇩ Exportar copia (.json)</button><button id="import-data" class="button">⇧ Importar copia</button><input type="file" id="restore-input" accept=".json,application/json" hidden/><button id="delete-data" class="button danger">Borrar mis datos</button></div></section>
 <section class="panel"><h2>Limitaciones</h2><p>Los apuntes en texto y herramientas locales vienen incluidos y funcionan sin conexión. La IA y el análisis de PDF/imágenes requieren Internet y una clave personal. No analiza automáticamente vídeos ni DOCX: pega una transcripción o convierte el documento a texto.</p></section>`;}
function bindSettings(){
 $("#save-ai").addEventListener("click",async()=>{const key=$("#gemini-key").value.trim();const model=$("#gemini-model").value.trim();if(!/^[a-zA-Z0-9._-]{3,65}$/.test(model))return toast("Modelo no válido.",true);st.config.model=model;await persist("ff_config",st.config);let saved=false;if(key){if($("#remember-key").checked&&window.FocusForgeAndroid?.saveGeminiKey){try{saved=window.FocusForgeAndroid.saveGeminiKey(key);}catch(_){saved=false;}if(!saved)window.FocusForgeAndroid?.clearGeminiKey?.();}else window.FocusForgeAndroid?.clearGeminiKey?.();apiKey=key;await ffBridge.storage.session.set({ff_api_key:key});$("#gemini-key").value="";}toast(key&&$("#remember-key").checked&&!saved?"Clave activa ahora, pero no se pudo guardar cifrada en Android.":apiKey?saved?"Clave cifrada y lista para la próxima apertura.":"Conexión activa. Usa «Probar IA».":"Modelo guardado. Para conectar Gemini introduce tu clave.",!!(key&&$("#remember-key").checked&&!saved));updateChrome();});
 $("#test-ai").addEventListener("click",async()=>{if(busy)return;markBusy(true,"Probando Gemini…");try{const text=await gemini("Responde únicamente con una frase corta en español confirmando que puedes actuar como tutor de estudio.");toast(`Gemini responde: ${text.slice(0,140)}`);}catch(err){toast(err.message,true)}finally{markBusy(false);}});
 $("#forget-key").addEventListener("click",async()=>{apiKey="";window.FocusForgeAndroid?.clearGeminiKey?.();await ffBridge.storage.session.remove("ff_api_key");toast("Clave eliminada de la sesión y de esta tablet.");render();updateChrome();});
 $("#export-data").addEventListener("click",()=>{const data={format:"focusforge-0.1",createdAt:new Date().toISOString(),ff_config:st.config,ff_plan:st.plan,ff_stats:st.stats,ff_pet:st.pet,ff_materials:st.materials,ff_errors:st.errors,ff_chat:st.chat};const json=JSON.stringify(data,null,2);if(window.FocusForgeAndroid?.saveBackup){window.FocusForgeAndroid.saveBackup(json);toast("Elige dónde guardar la copia en Android.");return;}const blob=new Blob([json],{type:"application/json"});const url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download="focusforge-copia-"+new Date().toISOString().slice(0,10)+".json";document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);});
 $("#import-data").addEventListener("click",()=>$("#restore-input").click());
 $("#restore-input").addEventListener("change",async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>5*1024*1024)throw Error("Copia demasiado grande (máx. 5 MB).");const data=JSON.parse(await f.text());if(data.format!=="focusforge-0.1"||!Array.isArray(data.ff_materials)||!Array.isArray(data.ff_errors))throw Error("No es una copia de FocusForge válida.");if(st.session.phase!=="idle")throw Error("Detén primero tu sesión de estudio.");if(!confirm("¿Restaurar esta copia y reemplazar tus materiales, tarjetas e historial actuales?"))return;
   const config={...C.defaultConfig(),...data.ff_config,domains:C.cleanDomains(data.ff_config?.domains)};config.model=/^[a-zA-Z0-9._-]{3,65}$/.test(config.model)?config.model:"gemini-flash-latest";
   const plan=C.cleanPlan(data.ff_plan);
   const materials=data.ff_materials.slice(0,20).filter(m=>typeof m.name==="string"&&typeof m.text==="string").map(m=>({id:crypto.randomUUID(),name:m.name.slice(0,100),kind:String(m.kind||"TEXTO").slice(0,25),text:m.text.slice(0,35000),studyPlan:typeof m.studyPlan==="string"?m.studyPlan.slice(0,1500):"",lesson:safeLesson(m.lesson),at:Date.now()}));
   // Imported cards are new local cards; imported content will never be rendered as HTML.
   const errors=data.ff_errors.slice(0,200).filter(c=>typeof c.question==="string"&&typeof c.answer==="string").map(c=>({id:crypto.randomUUID(),subject:String(c.subject||"General").slice(0,65),question:c.question.slice(0,600),answer:c.answer.slice(0,700),aiHelp:typeof c.aiHelp==="string"?c.aiHelp.slice(0,900):"",successes:C.boundedInt(c.successes,0,4,0),dueAt:Math.max(Date.now(),Number(c.dueAt)||Date.now()),at:Date.now()}));
   const oldstats=data.ff_stats||{};const stats={...C.defaultStats(),xp:C.boundedInt(oldstats.xp,0,10000000,0),coins:C.boundedInt(oldstats.coins,0,10000000,0),minutes:C.boundedInt(oldstats.minutes,0,10000000,0),completed:C.boundedInt(oldstats.completed,0,1000000,0),history:[]};
   const oldpet=data.ff_pet||{};const pet={earned:stats.minutes,spent:Math.min(stats.minutes,C.boundedInt(oldpet.spent,0,10000000,0)),food:C.boundedInt(oldpet.food,0,100,65),water:C.boundedInt(oldpet.water,0,100,65),joy:C.boundedInt(oldpet.joy,0,100,65),interactions:C.boundedInt(oldpet.interactions,0,1000000,0),species:['dog','cat'].includes(oldpet.species)?oldpet.species:null,lastCareAt:C.boundedInt(oldpet.lastCareAt,0,Date.now()+86400000,0)};
   await ffBridge.storage.local.set({ff_config:config,ff_plan:plan,ff_stats:stats,ff_pet:pet,ff_materials:materials,ff_errors:errors,ff_chat:[]});toast("Copia restaurada. Conversaciones e IDs antiguos no se importan por seguridad.");navigate("dashboard");
  }catch(err){toast(err.message,true)}});
 $("#delete-data").addEventListener("click",async()=>{if(!confirm("Esto eliminará permanentemente materiales, tarjetas y estadísticas de ESTE perfil. ¿Continuar?"))return;try{await msg("STOP");window.FocusForgeAndroid?.clearGeminiKey?.();await ffBridge.storage.local.clear();await ffBridge.storage.session.clear();apiKey="";st={config:C.defaultConfig(),plan:[...C.DEFAULT_PLAN],stats:C.defaultStats(),session:C.defaultSession(),materials:[],errors:[],chat:[],pet:C.defaultPet()};await ffBridge.storage.local.set({ff_config:st.config,ff_plan:st.plan,ff_stats:st.stats,ff_pet:st.pet,ff_session:st.session});toast("Datos borrados en este perfil.");navigate("dashboard");}catch(err){toast(err.message,true)}});
}
init().catch(err=>{$("#view").textContent="No se pudo iniciar la aplicación: "+err.message;console.error(err);});
